mapper.select:
SELECT r.RESERVATION_ID, r.USER_ID, r.ASSET_ID, r.START_TIME, r.END_TIME, r.PURPOSE, r.STATUS, r.ADDRESS, r.ADDRESS_STATE, r.ADDRESS_CITY, r.CREATED_AT, r.UPDATED_AT, a.NAME as ASSET_NAME, a.CATEGORY as ASSET_CATEGORY, a.COMPANY as ASSET_COMPANY, a.IMAGE as ASSET_IMAGE FROM RESERVATION r JOIN ASSET a ON r.ASSET_ID = a.ASSET_ID WHERE r.USER_ID = #{userId} AND a.IS_DELETED = '0'
AND r.STATUS = #{status}
AND r.START_TIME >= #{startDate}
AND r.END_TIME <= #{endDate}
AND a.CATEGORY = #{category}
ORDER BY r.CREATED_AT DESC

mapper.update:
UPDATE RESERVATION 
SET STATUS = 'CANCELLED',
    UPDATED_AT = SYSDATE
WHERE RESERVATION_ID = #{reservationId}
AND USER_ID = #{userId}
AND STATUS = 'PENDING'

mapper.select:
SELECT ul.USAGE_LOG_ID, ul.RESERVATION_ID, ul.USER_ID, ul.ASSET_ID, ul.START_TIME, ul.END_TIME, ul.USAGE_DURATION, ul.USAGE_STATUS, ul.PROCESSED_BY, ul.CREATED_AT, ul.UPDATED_AT, r.PURPOSE, r.STATUS as RESERVATION_STATUS, a.NAME as ASSET_NAME, a.CATEGORY as ASSET_CATEGORY, a.COMPANY as ASSET_COMPANY, a.IMAGE as ASSET_IMAGE, u.NAME as PROCESSED_BY_NAME FROM USAGE_LOG ul JOIN RESERVATION r ON ul.RESERVATION_ID = r.RESERVATION_ID JOIN ASSET a ON ul.ASSET_ID = a.ASSET_ID LEFT JOIN USERS u ON ul.PROCESSED_BY = u.USER_ID WHERE ul.USER_ID = #{userId} AND a.IS_DELETED = '0'
AND ul.START_TIME >= #{startDate}
AND ul.END_TIME <= #{endDate}
AND a.CATEGORY = #{category}
AND ul.USAGE_STATUS = #{usageStatus}
ORDER BY ul.CREATED_AT DESC
